#!/bin/bash

# Generate art icon options JSON from SVG files in icons/fill/art/
# Output: src/static/icons-autogenerated/json-list-art-icons.liquid

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
ICONS_DIR="$PROJECT_ROOT/icons/fill/art"
OUTPUT_FILE="$PROJECT_ROOT/src/static/icons-autogenerated/json-list-art-icons.liquid"

# Folder name remappings - add entries to this function as needed
get_group_name() {
  local folder="$1"
  case "$folder" in
    food)     echo "Food & Allergy" ;;
    clothing) echo "Clothing & Fabric" ;;
    *)
      # Default: capitalize each word
      echo "$folder" | sed 's/-/ /g' | awk '{for(i=1;i<=NF;i++) $i=toupper(substr($i,1,1)) tolower(substr($i,2))}1'
      ;;
  esac
}

# Capitalize first letter of first word, keep rest as-is with spaces
format_label() {
  local name="$1"
  # Replace hyphens with spaces
  name="${name//-/ }"
  # Capitalize first letter only
  echo "$(echo "${name:0:1}" | tr '[:lower:]' '[:upper:]')${name:1}"
}

# Start JSON array
echo "[" > "$OUTPUT_FILE"

first_item=true

# Iterate through category folders (sorted for consistent output)
for category_dir in $(ls -d "$ICONS_DIR"/*/ 2>/dev/null | sort); do
  [ -d "$category_dir" ] || continue

  category=$(basename "$category_dir")
  group=$(get_group_name "$category")

  # Iterate through SVG files in category (sorted)
  for svg_file in $(ls "$category_dir"*.svg 2>/dev/null | sort); do
    [ -f "$svg_file" ] || continue

    # Get filename without extension
    filename=$(basename "$svg_file" .svg)

    # Build value: fill-art-{category}-{filename}
    value="fill-art-$category-$filename"

    # Build label: capitalize first word
    label=$(format_label "$filename")

    # Add comma before item (except first)
    if [ "$first_item" = true ]; then
      first_item=false
    else
      echo "," >> "$OUTPUT_FILE"
    fi

    # Write JSON object (no trailing comma)
    printf '  {"value": "%s", "label": "%s", "group": "%s"}' "$value" "$label" "$group" >> "$OUTPUT_FILE"
  done
done

# Close JSON array
echo "" >> "$OUTPUT_FILE"
echo "]" >> "$OUTPUT_FILE"

echo "Generated: $OUTPUT_FILE"
echo "Total icons: $(grep -c '"value"' "$OUTPUT_FILE")"
